import json
def solve(g):
    Hh,Ww=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(c for row in g for c in row)
    bg=cnt.most_common(1)[0][0]
    out=[[bg]*Ww for _ in range(Hh)]
    # find candidate rectangles: contiguous block of same color c (c!=bg) that's fully that color
    seen=set()
    rects=[]
    for y in range(Hh):
        for x in range(Ww):
            c=g[y][x]
            if c!=bg and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); ys=[y]; xs=[x]
                while st:
                    yy,xx=st.pop()
                    for dy2,dx2 in ((0,1),(1,0)):
                        ny,nx=yy+dy2,xx+dx2
                        if 0<=ny<Hh and 0<=nx<Ww and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx)); ys.append(ny); xs.append(nx)
                rs=(min(ys),max(ys),min(xs),max(xs))
                inb=sum(1 for r in range(rs[0],rs[1]+1) for cc in range(rs[2],rs[3]+1) if g[r][cc]==c)
                tot=(rs[1]-rs[0]+1)*(rs[3]-rs[2]+1)
                if inb==tot and tot>=9:
                    rects.append((c,rs))
    for c,(r0,r1,c0,c1) in rects:
        for y in range(r0,r1+1):
            for x in range(c0,c1+1):
                out[y][x]=c
    return out
