def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    def cc(start):
        s={start}; st=[start]; c=g[start[0]][start[1]]
        while st:
            y,x=st.pop()
            for dy,dx in ((0,1),(1,0)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and (ny,nx) not in s:
                    s.add((ny,nx)); st.append((ny,nx))
        return c,s
    cs=[]; seen=set()
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                c,s=cc((y,x)); cs.append((c,s)); seen|=s
    # pick most-sold component: max cells/bboxarea ; tie-break larger cellcount
    def score(c,s):
        ys=[p[0] for p in s]; xs=[p[1] for p in s]
        return -len(s)/((max(ys)-min(ys)+1)*(max(xs)-min(xs)+1))
    c,bestcells=sorted(cs,key=lambda t:score(t[0],t[1]))[0]
    out=[[c if (y,x) in set(bestcells) else bg for x in range(W)] for y in range(H)]
    return out
