import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(v) for v in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import Counter
def comps(g,bg):
    H,W=len(g),len(g[0]); out=[]; seen=set()
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                s={(y,x)}; st=[(y,x)]; cc=g[y][x]
                while st:
                    yy,xx=st.pop()
                    for dy,dx in ((0,1),(1,0)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==cc and (ny,nx) not in s:
                            s.add((ny,nx)); st.append((ny,nx))
                out.append((cc,s)); seen|=s
    return out
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    cs=comps(g,bg)
    big=max(cs,key=lambda t:(len(t[1]),-(max(p[0] for p in t[1])-min(p[0] for p in t[1]))*(max(p[1] for p in t[1])-min(p[1] for p in t[1]))))
    return [[big[0] if (y,x) in set(big[1]) else bg for x in range(W)] for y in range(H)]
